
'use strict';
// Local UX prototype. The other players and room membership are simulated.
// A stable roster slot belongs to a player for the entire evening; it is never sorted.
const COPY={
 title:'Blindstop',tagline:'Count in your head.<br>Trust your timing.',closest:'Closest guess wins.',create:'Create room',join:'Join with code',back:'Back',help:'How to play',room:'Room',invite:'Invite',options:'Options',close:'Close',cancel:'Cancel',name:'Your name',nameHelp:'A nickname is enough.',namePlaceholder:'Your nickname',code:'Room code',codeHelp:'Five characters from your host.',face:'Choose your face',more:'More faces',faceLabel:'Choose face {n}',joinTitle:'Join the room',createTitle:'Make room for everyone.',joinAction:'Join room',nameError:'Enter a name, up to 12 characters.',codeError:'Enter a five-character code.',badAlphabet:'Use letters and numbers, without I, O, 0 or 1.',qrReady:'Joining room {code}',meta:'2–8 players · 10 rounds · about 4 minutes',players:'Players',timing:'Timing',place:'Place',points:'Points',status:'Status',average:'Avg. error',you:'you',host:'host',youHost:'you · host',ready:'Ready',counting:'Counting',locked:'Locked',left:'Left',start:'Start game',waitFor:'Waiting for {name}',waitToStart:'The host starts when everyone is ready.',needPlayer:'Waiting for one more player',joined:'{n} of 8 players',round:'Round {n} of 10',target:'Stop at',countStarts:'Count when the countdown disappears.',getReady:'Get ready',tap:'Tap',countSilently:'Count in your head.',tapSaved:'Locked in',noTap:'No tap',waiting:'Waiting for {n} more',waitingLast:'Waiting for the last player',waitingNone:'Everyone is ready',hiddenResult:'Your result appears when everyone finishes.',recorded:'Your tap is recorded',early:'early',late:'late',exact:'On target',yourTiming:'Your timing',targetWas:'Target {target} s',winnerRound:'{name} was closest',tieRound:'{n} players tied',noWinner:'No taps this round',penalty:'3.00 s penalty',next:'Next round in {n}s',finalIn:'Final results in {n}s',roundFinished:'Round complete',final:'Game finished',wins:'{name} wins',tieWins:'{n} players tied for first',yourAverage:'Your average: {n} s',again:'Play again',backRoom:'Back to room',onlyHost:'{name} starts the next game',evening:'The evening',games:'{n} games played',oneGame:'1 game played',total:'Total',endEvening:'End the evening',share:'Share results',newRoom:'Start a new room',earlyInsight:'You went early in {n} of {total} rounds.',lateInsight:'You went late in {n} of {total} rounds.',neutralInsight:'Your average error was {n} s.',noRounds:'No completed rounds yet.',thanks:'That was your evening.',emptySummary:'No games completed.',returnTitle:'Your room is still here.',rejoin:'Rejoin room',newInstead:'Start a new room',roomGone:'Room not found',roomGoneBody:'Check the code with your host. The room may have closed.',editCode:'Try another code',home:'Back to start',fullTitle:'This room is full',fullBody:'All eight seats are taken. Ask the host to free a seat.',retry:'Try again',playTitle:'A game is underway',playBody:'New players can join between games.',leaveTitle:'Leave this room?',leaveBody:'You can return while the room is still open.',leave:'Leave room',endTitle:'End the evening for everyone?',endBody:'Everyone will see the final table. This room will close.',endConfirm:'End and show results',stopTitle:'End this game?',stopBody:'Completed games keep their points. This unfinished game adds no points.',stop:'End game',removeTitle:'Remove {name}?',removeBody:'Their points from completed games stay in the evening total.',remove:'Remove player',removeShort:'Remove',manage:'Manage players',removeLabel:'Manage {name}',copy:'Copy code',copied:'Code copied',copyFail:'Select the code and copy it.',qrLabel:'Room code {code}',inviteBody:'Show the code to your friends, or read it aloud.',rules1:'Everyone gets the same target time.',rules2:'When the countdown disappears, count silently in your head.',rules3:'Tap the button when you think the target time has passed.',rules4:'Closest wins the round. Lowest average error wins the game.',rulesNote:'10 rounds. The next round starts automatically.',gotIt:'Got it',shareTitle:'Our Blindstop evening',shareHeader:'Blindstop · {n} games',shareLine:'{rank}. {name} — {points} pts',sharedCopy:'Results copied',shareFallback:'Copy this into your group chat.',reconnectTitle:'Ready to return?',reconnectBody:'Your game paused while your phone was away.',resume:'Continue game',paused:'Round paused',tapAgain:'Count from the beginning.',lobbyReturn:'The room and points stay with you.',savedRoom:'Room {code}',liveSummary:'Tonight’s points',noChanges:'No scores yet',seconds:'seconds',newHost:'{name} is now the host',leftRoom:'You left the room',leaveOrStay:'Stay in room',exactNumber:'0.00',finalMeta:'10 rounds · lower error wins',noTapShort:'No tap',pointsUnit:'{n} pts',nameSuffix:'{name} {n}',freeSeat:'Free seat',creatorNote:'Invite your friends, then start.',roomCodeSelect:'Select room code',codeName:'K7QMX'
};
const tr=(key,values={})=>(COPY[key]??key).replace(/\{(\w+)\}/g,(_,k)=>String(values[k]??''));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(k,v)=>esc(tr(k,v));
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const colors=['tYel','tRed','tBlu','tPur','tGrn','tOrg','tPnk','tGry'];
const names=['Artur','Mila','Tom','Ola','Kate','Noah','Alex','Lena'];
let people=names.map((name,id)=>({id,name,face:id+1,tile:colors[id],active:id<5,seen:id<5,total:0,history:[],allHistory:[]}));
let S={screen:'home',mode:'create',name:'',face:1,facePage:0,me:0,host:0,code:'K7QMX',draftCode:'',round:1,target:7,games:0,results:[],locked:false,started:0,live:false,countdown:3,left:false};
let jobs=[],ticker=null,epoch=0,toastTimer=null,invoker=null;
const active=()=>people.filter(p=>p.active),seen=()=>people.filter(p=>p.seen),self=()=>people[S.me];
const ico=(id,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 ${['sw','door'].includes(id)?'100 100':'24 24'}"><use href="#${id}"/></svg>`;
function avatar(p){return `<span class="avatar" style="--tile:var(--${p.tile})"><svg viewBox="90 90 900 900" aria-hidden="true"><use href="#face${p.face}"/></svg></span>`}
function button(key,action,style='primary',attrs='',values={}){return `<button type="button" class="button ${style}" data-action="${action}" ${attrs}>${t(key,values)}</button>`}
function header(middle='',left='back',right='help'){return `<header class="header"><div>${left?`<button data-action="${left}">${t(left==='menu'?'room':left)}</button>`:'<span></span>'}</div><div class="middle">${middle}</div><div class="right">${right?`<button data-action="${right}">${t(right)}</button>`:''}</div></header>`}
function footer(primary='',secondary='',meta=''){return `<footer class="actions"><div class="action-meta" role="status">${meta}</div>${primary||'<div class="action-placeholder primary-slot hidden" aria-hidden="true">—</div>'}${secondary||'<div class="action-placeholder hidden" aria-hidden="true">—</div>'}</footer>`}
function status(key,v={}){return `<div class="action-placeholder primary-slot" role="status">${t(key,v)}</div>`}
function shell(head,body,foot,cls=''){return `<div class="shell ${cls}">${head}<section class="body">${body}</section>${foot}</div>`}
function stopTimers(){epoch++;jobs.forEach(clearTimeout);jobs=[];clearInterval(ticker);ticker=null}
function schedule(fn,ms){const id=epoch;jobs.push(setTimeout(()=>{if(id===epoch)fn()},Math.max(0,ms)))}
function screen(name,{keepTimers=false}={}){if(!keepTimers)stopTimers();if(dialog.open)dialog.close();S.screen=name;render();}
function rank(list,metric,p){return 1+list.filter(x=>metric(x)<metric(p)-1e-8).length}
function mean(p){return p.history.length?p.history.reduce((sum,r)=>sum+(r.error===null?3:Math.abs(r.error)),0)/p.history.length:0}
function place(p){return rank(active(),mean,p)}
function roundMetric(p){const r=S.results.find(x=>x.id===p.id);return r&&r.error!==null?Math.abs(r.error):3}
function errorText(error){return error===null?t('noTapShort'):(error<0?'−':'+')+Math.abs(error).toFixed(2)+' s'}
function roundWinners(){const valid=S.results.filter(x=>x.error!==null);if(!valid.length)return [];const min=Math.min(...valid.map(x=>Math.abs(x.error)));return valid.filter(x=>Math.abs(Math.abs(x.error)-min)<1e-8).map(x=>people[x.id])}
function winners(list,metric,descending=false){if(!list.length)return [];const scores=list.map(metric),best=descending?Math.max(...scores):Math.min(...scores);return list.filter(p=>Math.abs(metric(p)-best)<1e-8)}
function winnersText(list,round=false){return list.length===0?t('noWinner'):list.length===1?t(round?'winnerRound':'wins',{name:list[0].name}):t(round?'tieRound':'tieWins',{n:list.length})}
function role(p){return p.id===S.me?(p.id===S.host?t('youHost'):t('you')):p.id===S.host?t('host'):p.active?'':t('left')}
function playerFields(p,mode){if(!p.active&&mode!=='summary')return {value:t('left'),position:'—',quiet:true};if(mode==='lobby')return {value:t(p.active?'ready':'left'),position:S.games?p.total:'—',quiet:true};if(mode==='waiting'){const done=S.results.some(r=>r.id===p.id);return {value:done?ico('t'):t('counting'),position:'—',aria:done?tr('locked'):tr('counting'),quiet:!done}}if(mode==='roundResult'){const r=S.results.find(x=>x.id===p.id);return {value:r?errorText(r.error):'—',position:r?'#'+rank(active(),roundMetric,p):'—',quiet:false}}if(mode==='final')return {value:mean(p).toFixed(2)+' s',position:'+'+(active().length-place(p)+1),quiet:false};if(mode==='summary')return {value:t('pointsUnit',{n:p.total}),position:'#'+(1+seen().filter(x=>x.total>p.total).length),quiet:false};return {value:'—',position:'—'}}
function roster(mode){const heading={lobby:['status','points'],waiting:['status','place'],roundResult:['timing','place'],final:['average','points'],summary:['total','place']}[mode];return `<div class="roster" aria-label="${t('players')}"><div class="table-head"><span class="people-label">${t('players')}</span><span class="value">${t(heading[0])}</span><span class="position">${t(heading[1])}</span></div>${people.map(p=>{if(!p.seen)return `<div class="player vacant" aria-hidden="true"></div>`;const f=playerFields(p,mode);return `<div class="player ${p.id===S.me?'self':''} ${p.active?'':'absent'}" data-player-slot="${p.id}">${avatar(p)}<div class="identity"><div class="name"><span>${esc(p.name)}</span></div><span class="role">${role(p)}</span></div><div class="value ${f.quiet?'quiet':''}" ${f.aria?`aria-label="${esc(f.aria)}"`:''}>${f.value}</div><div class="position">${f.position}</div></div>`}).join('')}</div>`}
function intro(){return shell(header(t('title'),'','help'),`<div class="center-body">${ico('sw','watch')}<div class="landing-text"><h1>${t('title')}</h1><p>${tr('tagline')}</p><p class="muted">${t('closest')}</p></div></div>`,footer(button('create','create'),button('join','join','secondary'),t('meta')))}
function form(){const join=S.mode==='join',prefill=S.screen==='qrjoin';return shell(header(t('title'),'back','help'),`<form id="identity-form" class="form-body" novalidate><h2>${t(join?'joinTitle':'createTitle')}</h2>${join?(prefill?`<div class="notice">${t('qrReady',{code:S.code})}</div><input type="hidden" name="code" value="${S.code}">`:`<div class="field"><label for="code">${t('code')}</label><input name="code" id="code" class="code-input" value="${esc(S.draftCode)}" maxlength="5" autocomplete="off" autocapitalize="characters" spellcheck="false" aria-describedby="code-help"><p class="help" id="code-help">${t('codeHelp')}</p></div>`):''}<div class="field"><label for="name">${t('name')}</label><input name="name" id="name" maxlength="12" autocomplete="nickname" value="${esc(S.name)}" placeholder="${t('namePlaceholder')}" aria-describedby="form-error"><p class="help">${t('nameHelp')}</p></div><div><div class="face-top"><span class="face-label">${t('face')}</span>${button('more','faces','quiet')}</div><div class="faces">${Array.from({length:4},(_,i)=>{let f=S.facePage*4+i+1;return `<button type="button" class="face-button" data-action="face" data-id="${f}" style="--tile:var(--${colors[S.me]})" aria-pressed="${S.face===f}" aria-label="${t('faceLabel',{n:f})}"><svg viewBox="90 90 900 900" aria-hidden="true"><use href="#face${f}"/></svg></button>`}).join('')}</div></div><p class="error" id="form-error" role="alert"></p></form>`,footer(`<button type="submit" class="button primary" form="identity-form">${t(join?'joinAction':'create')}</button>`,button(join?'create':'join',join?'create':'join','secondary')))}
function lobby(){const host=S.me===S.host;return shell(header(t('title'),'menu','invite'),`<div class="focal"><p class="meta">${t('code')}</p><p class="room-code">${esc(S.code)}</p><p class="message">${t('joined',{n:active().length})}${S.games?' · '+t(S.games===1?'oneGame':'games',{n:S.games}):''}</p></div>${roster('lobby')}`,footer(host?button(active().length>=2?'start':'needPlayer','start','primary',active().length<2?'disabled':''):status('waitFor',{name:people[S.host].name}),host&&S.games?button('endEvening','endEvening','secondary'):button('help','help','secondary'),host?t('meta'):t('waitToStart')))}
function timing(){const counting=S.screen==='countdown';return shell(header(t('round',{n:S.round}),'menu',''),`<div class="timing"><div class="timing-content"><p class="meta">${t('target')}</p><p class="target">${S.target.toFixed(2)} <small>s</small></p><div class="count-holder ${counting?'':'silent'}" ${counting?'':'aria-hidden="true"'}><svg viewBox="0 0 200 200" aria-hidden="true"><use href="#ring"/></svg><span class="count-digit" id="count">${S.countdown}</span></div><p class="meta ${counting?'':'silent'}">${t('countStarts')}</p></div></div>`,footer(counting?button('getReady','none','primary','disabled'):button('tap','tap','primary tap','id="tap"'),'',counting?'':t('countSilently')))}
function waiting(){const own=S.results.find(x=>x.id===S.me),remaining=active().length-S.results.length;return shell(header(t('round',{n:S.round}),'menu',''),`<div class="focal">${ico('t','locked-mark')}<h2>${t(own?.error===null?'noTap':'tapSaved')}</h2><p class="message">${t(remaining===1?'waitingLast':'waiting',{n:remaining})}</p></div>${roster('waiting')}`,footer(status('recorded'),'',t('hiddenResult')))}
function roundResult(){const own=S.results.find(x=>x.id===S.me),error=own?.error??null;return shell(header(t('round',{n:S.round}),'menu',''),`<div class="focal"><p class="meta">${t('yourTiming')}</p>${error===null?`<h2>${t('noTap')}</h2><p class="meta">${t('penalty')}</p>`:error===0?`<p class="number">0.00 <small>s</small></p><p class="meta">${t('exact')}</p>`:`<p class="number">${Math.abs(error).toFixed(2)} <small>s ${t(error<0?'early':'late')}</small></p>`}<p class="message">${winnersText(roundWinners(),true)}</p></div>${roster('roundResult')}<div class="progress" aria-hidden="true"><span id="progress"></span></div>`,footer(`<div class="action-placeholder primary-slot" id="next-label" role="status">${t(S.round===10?'finalIn':'next',{n:3})}</div>`,'',t('targetWas',{target:S.target.toFixed(2)})))}
function final(){const host=S.me===S.host;return shell(header(t('final'),'menu',''),`<div class="focal"><h2>${winnersText(winners(active(),mean))}</h2><p class="message">${t('yourAverage',{n:mean(self()).toFixed(2)})}</p></div>${roster('final')}`,footer(host?button('again','start'):status('onlyHost',{name:people[S.host].name}),button('backRoom','lobby','secondary'),t('finalMeta')))}
function insight(){const h=self().allHistory;if(!h.length)return t('noRounds');const early=h.filter(r=>r.error!==null&&r.error<0).length,late=h.filter(r=>r.error!==null&&r.error>0).length;if(early>h.length/2)return t('earlyInsight',{n:early,total:h.length});if(late>h.length/2)return t('lateInsight',{n:late,total:h.length});return t('neutralInsight',{n:(h.reduce((s,r)=>s+(r.error===null?3:Math.abs(r.error)),0)/h.length).toFixed(2)})}
function summary(){return shell(header(t('evening'),'',''),`<div class="focal"><p class="meta">${t(S.games===1?'oneGame':'games',{n:S.games})}</p><h2>${S.games?winnersText(winners(seen(),p=>p.total,true)):t('emptySummary')}</h2><p class="message">${S.games?insight():t('thanks')}</p></div>${roster('summary')}`,footer(button('share','share'),button('newRoom','new','secondary')), 'summary')}
function returning(){return shell(header(t('title'),'back','help'),`<div class="center-body">${ico('sw','watch')}<h2>${t('returnTitle')}</h2><div class="recall"><p class="meta">${t('code')}</p><p class="room-code">${esc(S.code)}</p></div><p class="meta">${t('lobbyReturn')}</p></div>`,footer(button('rejoin','rejoin'),button('newInstead','new','secondary')))}
function edge(){const map={gone:['roomGone','roomGoneBody','editCode','join'],full:['fullTitle','fullBody','retry','join'],playing:['playTitle','playBody','retry','join'],paused:['reconnectTitle','reconnectBody','resume','resume']};const c=map[S.screen]||map.gone;return shell(header(t('title'),'back','help'),`<div class="center-body">${ico('door','watch')}<h2>${t(c[0])}</h2><p class="muted">${t(c[1])}</p></div>`,footer(button(c[2],c[3]),button(S.screen==='paused'?'backRoom':'home',S.screen==='paused'?'lobby':'home','secondary')))}
function render(){app.innerHTML=S.screen==='home'?intro():['form','qrjoin'].includes(S.screen)?form():S.screen==='lobby'?lobby():['countdown','round'].includes(S.screen)?timing():S.screen==='waiting'?waiting():S.screen==='roundResult'?roundResult():S.screen==='final'?final():S.screen==='summary'?summary():S.screen==='return'?returning():edge();}
function remember(){const n=document.getElementById('name'),c=document.getElementById('code');if(n)S.name=n.value;if(c)S.draftCode=c.value;}
function resetRoom(){people=names.map((name,id)=>({id,name,face:id+1,tile:colors[id],active:id<5,seen:id<5,total:0,history:[],allHistory:[]}));S.games=0;S.round=1;S.host=0;S.left=false;S.results=[];S.live=false;S.code='K7QMX';}
function startGame(hostInitiated=false){if(active().length<2||(!hostInitiated&&S.me!==S.host))return;people.forEach(p=>p.history=[]);S.round=1;S.target=7;S.results=[];S.live=true;startCountdown()}
function startCountdown(){stopTimers();S.results=[];S.locked=false;S.countdown=3;S.screen='countdown';render();const id=epoch;ticker=setInterval(()=>{if(id!==epoch)return;S.countdown--;if(S.countdown===0)startRound();else{const el=document.getElementById('count');if(el)el.textContent=S.countdown}},1000)}
function startRound(){stopTimers();S.started=performance.now();S.results=[];S.locked=false;S.screen='round';render();for(const p of active()){if(p.id===S.me)continue;const error=Math.sin(S.round*7.1+p.id*3.7)*.82+(p.id%3)*.13;schedule(()=>record(p.id,error),Math.max(.15,S.target+error)*1000)}schedule(()=>{for(const p of active())if(!S.results.some(r=>r.id===p.id))S.results.push({id:p.id,error:null});S.locked=true;completeRound()},(S.target+8)*1000);}
function record(id,error){if(!['round','waiting'].includes(S.screen)||S.results.some(r=>r.id===id))return;S.results.push({id,error});if(id===S.me){S.locked=true;S.screen='waiting';render()}else if(S.screen==='waiting')updateWaiting();if(S.results.length===active().length)completeRound()}
function updateWaiting(){const focusAction=document.activeElement?.dataset?.action;render();if(focusAction){const el=app.querySelector(`[data-action="${focusAction}"]`);el?.focus({preventScroll:true})}}
function tap(){if(S.screen!=='round'||S.locked)return;record(S.me,(performance.now()-S.started)/1000-S.target)}
function completeRound(){if(S.screen==='roundResult')return;stopTimers();for(const p of active()){const r=S.results.find(x=>x.id===p.id)||{error:null};p.history.push({error:r.error})}S.screen='roundResult';render();let remaining=3;const id=epoch;ticker=setInterval(()=>{if(id!==epoch)return;remaining--;const label=document.getElementById('next-label'),bar=document.getElementById('progress');if(label)label.textContent=tr(S.round===10?'finalIn':'next',{n:remaining});if(bar)bar.style.width=(remaining/3*100)+'%';if(remaining===0){stopTimers();if(S.round===10){for(const p of active()){p.total+=active().length-place(p)+1;p.allHistory.push(...p.history)}S.games++;S.live=false;screen('final')}else{S.round++;S.target=[7,4.5,9.25,6,11,3.75,8.5,5.25,10,7.75][S.round-1];startCountdown()}}},1000)}
function toast(key){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=tr(key);el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,2500)}
function openDialog(title,body,actions){invoker=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button type="button" class="close-button" data-action="dismiss" aria-label="${t('close')}">${ico('x')}</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${actions}</div>`;if(!dialog.open)dialog.showModal()}
function dismiss(){dialog.close();if(invoker?.isConnected)invoker.focus({preventScroll:true})}
function help(){openDialog(t('help'),`<ol><li>${t('rules1')}</li><li>${t('rules2')}</li><li>${t('rules3')}</li><li>${t('rules4')}</li></ol><p class="meta">${t('rulesNote')}</p>`,button('gotIt','dismiss'))}
function invite(){openDialog(t('invite'),`<img class="qr" src="data:image/png;base64," alt="${t('qrLabel',{code:S.code})}"><p class="room-code center" tabindex="0">${esc(S.code)}</p><p class="meta center">${t('inviteBody')}</p>`,button('copy','copy')+button('close','dismiss','secondary'))}
function menu(){const mid=['countdown','round','waiting','roundResult'].includes(S.screen),host=S.me===S.host;openDialog(t('options'),'',(mid&&host?button('stop','stop','secondary'):'')+(!mid&&host?button('manage','manage','secondary'):'')+(!mid&&host?button('endEvening','endEvening','secondary'):'')+button('leave','leave','secondary')+button('cancel','dismiss','quiet'))}
function manage(){openDialog(t('manage'),`<div>${active().filter(p=>p.id!==S.me).map(p=>`<button class="player roster-button" data-action="remove" data-id="${p.id}" aria-label="${t('removeLabel',{name:p.name})}">${avatar(p)}<span class="identity"><span class="name">${esc(p.name)}</span></span><span class="value">${t('removeShort')}</span><span class="position">${ico('x')}</span></button>`).join('')}</div>`,button('close','dismiss','secondary'))}
async function copy(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}const box=document.createElement('textarea');box.value=text;(dialog.open?dialog:document.body).append(box);box.select();const ok=document.execCommand('copy');box.remove();return ok}catch{return false}}
async function share(){const sorted=[...seen()].sort((a,b)=>b.total-a.total||a.id-b.id);const text=[tr('shareHeader',{n:S.games}),...sorted.map(p=>tr('shareLine',{rank:1+sorted.filter(x=>x.total>p.total).length,name:p.name,points:p.total}))].join('\n');try{if(navigator.share){await navigator.share({title:tr('shareTitle'),text});return}}catch(err){if(err.name==='AbortError')return}if(await copy(text))toast('sharedCopy');else openDialog(t('share'),`<p>${t('shareFallback')}</p><textarea readonly aria-label="${t('share')}">${esc(text)}</textarea>`,button('close','dismiss','secondary'))}
async function action(a,el){remember();switch(a){case 'home':screen('home');break;case 'back':screen(['form','qrjoin','return','gone','full','playing'].includes(S.screen)?'home':'lobby');break;case 'create':S.mode='create';S.me=0;screen('form');break;case 'join':S.mode='join';S.me=1;screen('form');break;case 'face':S.face=Number(el.dataset.id);render();document.querySelector(`[data-action="face"][data-id="${S.face}"]`)?.focus({preventScroll:true});break;case 'faces':S.facePage=1-S.facePage;S.face=S.facePage*4+1;render();document.querySelector('[data-action="faces"]')?.focus({preventScroll:true});break;case 'start':startGame();break;case 'tap':tap();break;case 'lobby':S.live=false;screen('lobby');break;case 'help':help();break;case 'invite':invite();break;case 'menu':menu();break;case 'dismiss':dismiss();break;case 'copy':toast(await copy(S.code)?'copied':'copyFail');break;case 'share':await share();break;case 'new':resetRoom();S.mode='create';S.me=0;screen('form');break;case 'rejoin':S.left=false;screen('lobby');break;case 'resume':if(S.pausedFrom==='roundResult'){if(S.round===10){for(const p of active()){p.total+=active().length-place(p)+1;p.allHistory.push(...p.history)}S.games++;S.live=false;screen('final');break}S.round++;S.target=[7,4.5,9.25,6,11,3.75,8.5,5.25,10,7.75][S.round-1];}S.live=true;startCountdown();break;case 'endEvening':openDialog(t('endTitle'),`<p>${t('endBody')}</p>`,button('endConfirm','confirmEnd')+button('cancel','dismiss','secondary'));break;case 'confirmEnd':S.live=false;screen('summary');break;case 'stop':openDialog(t('stopTitle'),`<p>${t('stopBody')}</p>`,button('stop','confirmStop')+button('cancel','dismiss','secondary'));break;case 'confirmStop':S.live=false;screen('lobby');break;case 'leave':openDialog(t('leaveTitle'),`<p>${t('leaveBody')}</p>`,button('leave','confirmLeave')+button('leaveOrStay','dismiss','secondary'));break;case 'confirmLeave':S.left=true;S.live=false;screen('return');break;case 'manage':manage();break;case 'remove':{const p=people[Number(el.dataset.id)];openDialog(t('removeTitle',{name:p.name}),`<p>${t('removeBody')}</p>`,button('remove','confirmRemove','primary',`data-id="${p.id}"`)+button('cancel','dismiss','secondary'));break}case 'confirmRemove':people[Number(el.dataset.id)].active=false;screen('lobby');break;}}
app.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)action(el.dataset.action,el)});dialog.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el)action(el.dataset.action,el)});
app.addEventListener('input',event=>{if(event.target.id==='code')event.target.value=event.target.value.toUpperCase().replace(/\s/g,'')});
app.addEventListener('submit',event=>{event.preventDefault();remember();const data=new FormData(event.target),name=String(data.get('name')||'').trim(),code=String(data.get('code')||'').trim().toUpperCase();let error='';if(!name||name.length>12)error='nameError';else if(S.mode==='join'&&code.length!==5)error='codeError';else if(S.mode==='join'&&!/^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{5}$/.test(code))error='badAlphabet';if(error){document.getElementById('form-error').textContent=tr(error);document.getElementById(error==='nameError'?'name':'code')?.focus();return}if(S.mode==='join'&&code!=='K7QMX'){screen('gone');return}let finalName=name,n=2;while(active().some(p=>p.id!==S.me&&p.name.toLowerCase()===finalName.toLowerCase())){const suffix=' '+n++;finalName=name.slice(0,12-suffix.length)+suffix}S.name=name;self().name=finalName;const previousFace=self().face;const sameFace=active().find(p=>p.id!==S.me&&p.face===S.face);if(sameFace)sameFace.face=previousFace;self().face=S.face;S.live=false;S.left=false;screen('lobby');if(S.me!==S.host)schedule(()=>startGame(true),4000);});
// Pointer presses measure the intention at contact, not after finger release.
app.addEventListener('pointerdown',event=>{if(event.button!==0)return;const el=event.target.closest('[data-action="tap"]');if(el&&!el.disabled){event.preventDefault();tap()}});
app.addEventListener('keydown',event=>{if(event.repeat)return;if(event.target?.dataset?.action==='tap'&&[' ','Enter'].includes(event.key)){event.preventDefault();tap()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.live){stopTimers();S.live=false;if(dialog.open)dialog.close();S.pausedFrom=S.screen;S.screen='paused';render()}});window.addEventListener('pagehide',stopTimers);
const initial=new URLSearchParams(location.hash.slice(1));if(initial.get('join')){S.mode='join';S.me=1;S.draftCode='K7QMX';S.screen='qrjoin'}render();
